#!/usr/bin/env python3
"""Cleanliness check for the Markdown files (run before every wave; CLAUDE.md).

    python3 scripts/check_docs.py

Reports, for every tracked `.md` file outside `results/archive/` and `results/swarm/archive/`:
* links `[...](path)` to a file that does not exist;
* backticked repository paths (not in task briefs, which name files still to be created) (`Spaces/Foo.lean`, `results/BAR.md`, `scripts/x.py`, ...) that
  do not exist;
* generated files that are out of date (`results/TODO.md`, `results/PROGRESS.md`).
Exit 1 if anything is reported.
"""
import os, re, subprocess, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SKIP = ('results/archive/', 'results/swarm/archive/')
TOP = ('FourierMukai', 'WeakApprox', 'Spaces', 'SpacesVerified', 'results', 'scripts', 'ci')
PATH = re.compile(r'`((?:' + '|'.join(TOP) + r')/[A-Za-z0-9_./-]+\.(?:lean|md|py|sh|txt|yml|toml))`')
LINK = re.compile(r'\]\(([^)#\s]+)(?:#[^)]*)?\)')


def tracked():
    out = subprocess.run(['git', '-C', ROOT, 'ls-files', '*.md'], capture_output=True, text=True)
    return [p for p in out.stdout.split() if not p.startswith(SKIP)]


def regenerated(script, target):
    path = os.path.join(ROOT, target)
    before = open(path, encoding='utf8').read() if os.path.exists(path) else ''
    subprocess.run([sys.executable, os.path.join(ROOT, 'scripts', script)], capture_output=True)
    after = open(path, encoding='utf8').read()
    if before != after:
        return [f'{target}: was out of date (regenerated by scripts/{script}; commit it)']
    return []


def main():
    problems = []
    for md in tracked():
        base = os.path.dirname(md)
        for n, line in enumerate(open(os.path.join(ROOT, md), encoding='utf8'), 1):
            for target in LINK.findall(line):
                if re.match(r'[a-z]+:', target): continue
                if not os.path.exists(os.path.normpath(os.path.join(ROOT, base, target))):
                    problems.append(f'{md}:{n}: broken link {target}')
            # task briefs name the files a worker is to create: skip their path check
            if re.match(r'results/swarm/wave\d+/', md): continue
            for target in PATH.findall(line):
                if '*' in target or '<' in target: continue
                if not os.path.exists(os.path.join(ROOT, target)):
                    problems.append(f'{md}:{n}: missing path {target}')
    problems += regenerated('todo.py', 'results/TODO.md')
    problems += regenerated('progress.py', 'results/PROGRESS.md')
    for p in problems: print(p)
    print(f'check_docs: {len(problems)} problem(s) in {len(tracked())} Markdown files')
    sys.exit(1 if problems else 0)


if __name__ == '__main__':
    main()
